BEGIN;
SELECT plan(11);
INSERT INTO auth.users(id,email,raw_app_meta_data) VALUES('98000000-0000-4000-8000-000000000001','ntp-admin@example.com','{"role":"super_admin"}');
INSERT INTO public.workspaces(id,name) VALUES('98000000-0000-4000-8000-000000000002','NTP tests');
INSERT INTO public.organizations(id,tenant_id,name,kind) VALUES('98000000-0000-4000-8000-000000000003','98000000-0000-4000-8000-000000000002','Qualified firm','consultant');
INSERT INTO public.projects(id,workspace_id,name,project_type) VALUES('98000000-0000-4000-8000-000000000004','98000000-0000-4000-8000-000000000002','NTP project','construction');
INSERT INTO public.contractor_qualification_cases(id,tenant_id,organization_id,project_id,scope_type) VALUES('98000000-0000-4000-8000-000000000005','98000000-0000-4000-8000-000000000002','98000000-0000-4000-8000-000000000003','98000000-0000-4000-8000-000000000004','project');
INSERT INTO public.contractor_case_requirements(id,tenant_id,case_id,requirement_code,title,category,gate_type,expiration_required) VALUES('98000000-0000-4000-8000-000000000006','98000000-0000-4000-8000-000000000002','98000000-0000-4000-8000-000000000005','insurance','Insurance','insurance','work',true);
SELECT set_config('request.jwt.claims','{"sub":"98000000-0000-4000-8000-000000000001","role":"authenticated","app_metadata":{"role":"super_admin"}}',true);
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.configure_contractor_request('98000000-0000-4000-8000-000000000005','{}',false,false)$$,'an administrator can request nothing from a known firm');
SELECT is((SELECT portal_requested FROM public.contractor_case_requirements WHERE id='98000000-0000-4000-8000-000000000006'),false,'unchecked items are hidden');
SELECT is((SELECT work_ready FROM public.contractor_qualification_cases WHERE id='98000000-0000-4000-8000-000000000005'),false,'hiding an item does not falsely certify it');
SELECT throws_ok($$SELECT public.save_contractor_ntp('98000000-0000-4000-8000-000000000005','{}',true)$$,'P0001','Complete onboarding review before issuing the notice','incomplete qualification blocks NTP');
SELECT throws_ok($$SELECT public.record_contractor_prior_approval('98000000-0000-4000-8000-000000000006','Approved certificate',current_date-1)$$,'P0001','A current validity date is required','expired prior evidence cannot qualify');
SELECT lives_ok($$SELECT public.record_contractor_prior_approval('98000000-0000-4000-8000-000000000006','Previously reviewed certificate',current_date+90)$$,'existing approval can replace repeat upload');
SELECT is((SELECT work_ready FROM public.contractor_qualification_cases WHERE id='98000000-0000-4000-8000-000000000005'),true,'existing valid evidence clears readiness');
SELECT throws_ok($$SELECT public.save_contractor_ntp('98000000-0000-4000-8000-000000000005','{}',true)$$,'P0001','Confirm the approved contract or proposal and its approval date','missing agreement blocks issue');
SELECT lives_ok($$SELECT public.save_contractor_ntp('98000000-0000-4000-8000-000000000005',jsonb_build_object('agreement_reference','Approved scope 101','agreement_approved_on',current_date::text,'agreement_confirmed',true,'scope_of_work','Inspect the site','start_date',current_date::text,'completion_date',(current_date+14)::text,'budget_cents',200000,'prerequisites_confirmed',true,'recipient_email','firm@example.com'),true)$$,'complete release packet can be issued');
SELECT throws_ok($$SELECT public.save_contractor_ntp('98000000-0000-4000-8000-000000000005','{}',false)$$,'P0001','The issued notice is immutable. Use project correspondence for amendments','issued letters cannot be overwritten');
SELECT throws_ok($$UPDATE public.contractor_notices_to_proceed SET status='draft' WHERE case_id='98000000-0000-4000-8000-000000000005'$$,'42501',NULL,'direct edits cannot bypass the release function');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
